const tenant = $('Relatorio22h - Loop Tenants').item.json;

let eventosManha = [];
let eventosTarde = [];

try {
  const manhaItems = $('Relatorio22h - Buscar Manha').all();
  for (const item of manhaItems) {
    if (item.json && item.json.summary) {
      const start = item.json.start?.dateTime || item.json.start?.date || '';
      let hora = '--:--';
      if (start) {
        const d = new Date(start);
        hora = d.toLocaleTimeString('pt-BR', {hour: '2-digit', minute: '2-digit', timeZone: 'America/Sao_Paulo'});
      }
      const titulo = item.json.summary || 'Agendamento';
      eventosManha.push(`   🕐 ${hora} - ${titulo}`);
    }
  }
} catch(e) {}

try {
  const tardeItems = $('Relatorio22h - Buscar Tarde').all();
  for (const item of tardeItems) {
    if (item.json && item.json.summary) {
      const start = item.json.start?.dateTime || item.json.start?.date || '';
      let hora = '--:--';
      if (start) {
        const d = new Date(start);
        hora = d.toLocaleTimeString('pt-BR', {hour: '2-digit', minute: '2-digit', timeZone: 'America/Sao_Paulo'});
      }
      const titulo = item.json.summary || 'Agendamento';
      eventosTarde.push(`   🕑 ${hora} - ${titulo}`);
    }
  }
} catch(e) {}

const amanha = $('Relatorio22h - Montar Datas').first().json.amanha;
const [ano, mes, dia] = amanha.split('-');
const dataFormatada = `${dia}/${mes}/${ano}`;

const diasSemana = ['', 'Segunda-feira', 'Terça-feira', 'Quarta-feira', 'Quinta-feira', 'Sexta-feira', 'Sábado', 'Domingo'];
const diaSemanaNum = $('Relatorio22h - Montar Datas').first().json.dia_semana;
const diaNome = diasSemana[diaSemanaNum] || '';
const ehSabado = diaSemanaNum === 6;

const total = eventosManha.length + eventosTarde.length;

const nomeAtendente = tenant.nome_atendente_ia || 'Assistente';
const nomeEmpresa = tenant.nome_empresa || 'Empresa';

let relatorio = `📋 *RELATÓRIO DA AGENDA*\n`;
relatorio += `📅 *${diaNome}, ${dataFormatada}*\n`;
relatorio += `▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬\n\n`;

relatorio += `🌅 *MANHÃ (8h às 12h)*\n`;
if (eventosManha.length > 0) {
  relatorio += eventosManha.join('\n') + '\n';
} else {
  relatorio += `   ✅ Nenhum agendamento\n`;
}

if (ehSabado) {
  relatorio += `\n🕐 *Sábado: atendimento até 14h*\n`;
} else {
  relatorio += `\n🌇 *TARDE (14h às 20h)*\n`;
  if (eventosTarde.length > 0) {
    relatorio += eventosTarde.join('\n') + '\n';
  } else {
    relatorio += `   ✅ Nenhum agendamento\n`;
  }
}

relatorio += `\n▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬\n`;
relatorio += `📊 *Total: ${total} agendamento${total !== 1 ? 's' : ''}*\n`;
relatorio += `\n🤖 ${nomeAtendente} - ${nomeEmpresa}`;

return [{ json: { relatorio, total, data: dataFormatada } }];
